/* IKEA DNA — democratic blue and yellow, Skapa functionalism, price-tag boldness */
.theme-ikea-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.970 0 0);
  --surface-2: oklch(0.943 0 0);
  --fg: oklch(0.178 0 0);
  --fg-muted: oklch(0.402 0 0);
  --accent: oklch(0.460 0.140 252.7);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.895 0.184 97.0);
  --line: oklch(0.904 0 0);
  --success: oklch(0.550 0.186 142.1);
  --warning: oklch(0.683 0.182 41.6);
  --danger: oklch(0.579 0.229 13.3);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Noto Sans", sans-serif;
  --font-body: "Noto Sans", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.01em;
  --label-transform: none;
  --label-tracking: 0.04em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-ikea-dna h1,
.theme-ikea-dna h2,
.theme-ikea-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-ikea-dna { --font-ui: var(--font-display); }
.theme-ikea-dna h1 { font-weight: 900; }
.theme-ikea-dna h2 { background: var(--accent-2); display: inline-block; padding: 0.1em 0.35em; }
.theme-ikea-dna button { font-weight: 700; }

/* depth */
.theme-ikea-dna thead th { background: var(--accent); color: var(--accent-fg); font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; }
.theme-ikea-dna td { border-bottom: 1px solid var(--line); }
.theme-ikea-dna tbody tr:nth-child(even) { background: var(--surface); }
.theme-ikea-dna input, .theme-ikea-dna select, .theme-ikea-dna textarea { border: 1px solid oklch(0.60 0 0); border-radius: var(--radius-sm); background: var(--bg); }
.theme-ikea-dna input:focus-visible, .theme-ikea-dna select:focus-visible, .theme-ikea-dna textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.theme-ikea-dna a { color: var(--accent); font-weight: 700; text-decoration: underline; text-underline-offset: 2px; }
.theme-ikea-dna a:hover { background: var(--accent-2); color: oklch(0.178 0 0); text-decoration: none; }
.theme-ikea-dna ::selection { background: var(--accent-2); color: oklch(0.178 0 0); }
.theme-ikea-dna ::-webkit-scrollbar { width: 10px; }
.theme-ikea-dna ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-ikea-dna ::-webkit-scrollbar-thumb { background: var(--accent); border-radius: 0; }
.theme-ikea-dna kbd { font-family: var(--font-mono); font-size: 0.72em; background: var(--bg); border: 1px solid var(--fg); border-radius: 0; padding: 0.1em 0.4em; }
.theme-ikea-dna .label-caps { background: var(--accent-2); color: oklch(0.178 0 0); font-weight: 700; padding: 0.1em 0.4em; }
.theme-ikea-dna .themed-border { border-color: var(--accent); }
.theme-ikea-dna hr { border: none; border-top: 2px dotted var(--fg-muted); }
.theme-ikea-dna button:active { transform: translate(1px, 1px); }

/* alt mode: showroom at night — deep IKEA blue, price-tag yellow intact */
.theme-ikea-dna.alt-mode {
  --bg: oklch(0.185 0.045 252.7);
  --surface: oklch(0.225 0.050 252.7);
  --surface-2: oklch(0.265 0.055 252.7);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.74 0.03 252);
  --accent: oklch(0.895 0.184 97.0);
  --accent-fg: oklch(0.185 0.045 252.7);
  --line: oklch(1 0 0 / 16%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}
.theme-ikea-dna.alt-mode h2 { color: oklch(0.185 0.045 252.7); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
